def rewrite(v):
 if isinstance(v,str):return mapping.get(v,v).replace('\\r\\n','\n')
 if isinstance(v,list):return [rewrite(x) for x in v]
 if isinstance(v,dict):return {k:rewrite(x) for k,x in v.items()}
 return v
